#!/bin/bash
# Uninstall script for MuseScore
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling MuseScore..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping MuseScore if running..."
pkill -f "MuseScore" 2>/dev/null || true

# Remove /Applications/MuseScore 4.app
echo "Removing /Applications/MuseScore 4.app..."
if [ -d "/Applications/MuseScore 4.app" ]; then
    rm -rf "/Applications/MuseScore 4.app" 2>/dev/null || true
elif [ -f "/Applications/MuseScore 4.app" ]; then
    rm -f "/Applications/MuseScore 4.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/MuseScore
echo "Removing $HOME/Library/Application Support/MuseScore..."
if [ -d "$HOME/Library/Application Support/MuseScore" ]; then
    rm -rf "$HOME/Library/Application Support/MuseScore" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/MuseScore" ]; then
    rm -f "$HOME/Library/Application Support/MuseScore" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/MuseScore
echo "Removing $HOME/Library/Caches/MuseScore..."
if [ -d "$HOME/Library/Caches/MuseScore" ]; then
    rm -rf "$HOME/Library/Caches/MuseScore" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/MuseScore" ]; then
    rm -f "$HOME/Library/Caches/MuseScore" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/org.musescore.MuseScore
echo "Removing $HOME/Library/Caches/org.musescore.MuseScore..."
if [ -d "$HOME/Library/Caches/org.musescore.MuseScore" ]; then
    rm -rf "$HOME/Library/Caches/org.musescore.MuseScore" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/org.musescore.MuseScore" ]; then
    rm -f "$HOME/Library/Caches/org.musescore.MuseScore" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.musescore.MuseScore*.plist
echo "Removing $HOME/Library/Preferences/org.musescore.MuseScore*.plist..."
if [ -d "$HOME/Library/Preferences/org.musescore.MuseScore*.plist" ]; then
    rm -rf "$HOME/Library/Preferences/org.musescore.MuseScore*.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.musescore.MuseScore*.plist" ]; then
    rm -f "$HOME/Library/Preferences/org.musescore.MuseScore*.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/org.musescore.MuseScore.savedState
echo "Removing $HOME/Library/Saved Application State/org.musescore.MuseScore.savedState..."
if [ -d "$HOME/Library/Saved Application State/org.musescore.MuseScore.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/org.musescore.MuseScore.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/org.musescore.MuseScore.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/org.musescore.MuseScore.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
